        "            $timeout(tick, 10000);   // R1.3 - back to 10s (was 5s, too noisy)",
        "        };",
        "        $timeout(tick, 10000);",
        "    }",
        "",
        "    /* ============================================================",
        "     *  R1 - VISIBILITY RECOVERY",
